-- Roblox Universal MCP v2 plugin
local HttpService=game:GetService('HttpService') local Selection=game:GetService('Selection') local ChangeHistoryService=game:GetService('ChangeHistoryService') local LogService=game:GetService('LogService') local StudioTestService=game:GetService('StudioTestService') local RunService=game:GetService('RunService') local CollectionService=game:GetService('CollectionService')
local BRIDGE='http://127.0.0.1:58888' local TOKEN='roblox-universal-mcp-local' local VERSION='2.0.0' local sessionId=nil local connected=false local running=true local logs={} local MAX_LOGS=256
local toolbar=plugin:CreateToolbar('Universal MCP') local button=toolbar:CreateButton('Universal MCP','Connect Roblox Studio to AI through MCP','rbxassetid://14978048121') local widget=plugin:CreateDockWidgetPluginGui('RobloxUniversalMCP',DockWidgetPluginGuiInfo.new(Enum.InitialDockState.Float,false,false,360,180,300,140)) widget.Title='Roblox Universal MCP' local status=Instance.new('TextLabel') status.Size=UDim2.fromScale(1,1) status.BackgroundColor3=Color3.fromRGB(18,20,24) status.TextColor3=Color3.fromRGB(235,238,242) status.Font=Enum.Font.Gotham status.TextSize=14 status.TextWrapped=true status.Text='MCP: starting...' status.Parent=widget button.Click:Connect(function()widget.Enabled=not widget.Enabled end)
local function addLog(message,messageType) if #logs>=MAX_LOGS then table.remove(logs,1) end table.insert(logs,{message=message,type=tostring(messageType),time=os.time()}) end LogService.MessageOut:Connect(addLog) for _,e in ipairs(LogService:GetLogHistory()) do if e.message then addLog(e.message,e.messageType) end end
local function request(method,path,body) local options={Url=BRIDGE..path,Method=method,Headers={['Content-Type']='application/json',['X-Roblox-MCP-Token']=TOKEN}} if body then options.Body=HttpService:JSONEncode(body) end local ok,response=pcall(function()return HttpService:RequestAsync(options)end) if not ok then return false,tostring(response) end if not response.Success then return false,response.StatusMessage end local decoded,data=pcall(function()return HttpService:JSONDecode(response.Body)end) if not decoded then return false,'invalid json' end return true,data end
local function split(path) local out={} for part in string.gmatch(path or 'game','[^%.]+') do table.insert(out,part) end return out end
local function find(path) local p=split(path) local root=table.remove(p,1) local current=game if root and root~='game' and root~='DataModel' then current=game:FindFirstChild(root) end if not current then return nil end for _,name in ipairs(p) do current=current:FindFirstChild(name) if not current then return nil end end return current end
local function getPath(instance) if instance==game then return 'game' end local out={} local current=instance while current and current~=game do table.insert(out,1,current.Name) current=current.Parent end table.insert(out,1,'game') return table.concat(out,'.') end
local function encodeValue(value) local t=typeof(value) if t=='Color3' then return{__type='Color3',r=value.R,g=value.G,b=value.B} elseif t=='Vector3' then return{__type='Vector3',x=value.X,y=value.Y,z=value.Z} elseif t=='Vector2' then return{__type='Vector2',x=value.X,y=value.Y} elseif t=='CFrame' then return{__type='CFrame',components={value:GetComponents()}} elseif t=='BrickColor' then return{__type='BrickColor',number=value.Number} elseif t=='EnumItem' then return{__type='EnumItem',enum=tostring(value.EnumType),name=value.Name} elseif t=='Instance' then return{__type='Instance',path=getPath(value)} end return value end
local PROPS={'Anchored','CanCollide','CanTouch','CanQuery','Transparency','Material','Color','Size','Position','CFrame','CastShadow','Reflectance','Massless','CollisionGroup','Brightness','Range','Shadows','SoundId','Volume','PlaybackSpeed','Looped','Texture','TextureId','MeshId','AnimationId','Rate','Lifetime','Speed','LightEmission','LightInfluence','Text','TextColor3','TextTransparency','BackgroundColor3','BackgroundTransparency','Visible','Image','ImageColor3'}
local function readProps(instance) local out={} for _,property in ipairs(PROPS) do local ok,value=pcall(function()return instance[property]end) if ok and value~=nil then out[property]=encodeValue(value) end end return out end
local function serialize(instance,includeProperties) local out={name=instance.Name,className=instance.ClassName,path=getPath(instance)} if includeProperties then out.properties=readProps(instance) end return out end
local function setProp(instance,property,value) if type(value)=='table' and value.__type=='Color3' then value=Color3.new(value.r,value.g,value.b) elseif type(value)=='table' and value.__type=='Vector3' then value=Vector3.new(value.x,value.y,value.z) elseif type(value)=='table' and value.__type=='Vector2' then value=Vector2.new(value.x,value.y) elseif type(value)=='table' and value.__type=='CFrame' then value=CFrame.new(table.unpack(value.components)) elseif type(value)=='table' and value.__type=='BrickColor' then value=BrickColor.new(value.number) elseif type(value)=='table' and value.__type=='EnumItem' and Enum[value.enum] then value=Enum[value.enum][value.name] elseif type(value)=='table' and value.__type=='Instance' then value=find(value.path) end return pcall(function()instance[property]=value end) end
local function tree(root,depth,includeProperties) local function visit(instance,d) local node=serialize(instance,includeProperties) if d>0 then node.children={} for _,child in ipairs(instance:GetChildren()) do table.insert(node.children,visit(child,d-1)) end end return node end return visit(root,depth) end
local function search(root,query,mode,maxResults) local results={} local q=string.lower(query) local function matches(instance) if mode=='name' then return string.find(string.lower(instance.Name),q,1,true)~=nil elseif mode=='class' then return string.find(string.lower(instance.ClassName),q,1,true)~=nil elseif mode=='tag' then for _,tag in ipairs(CollectionService:GetTags(instance)) do if string.find(string.lower(tag),q,1,true) then return true end end elseif mode=='source' and instance:IsA('LuaSourceContainer') then local ok,source=pcall(function()return instance.Source end) return ok and string.find(string.lower(source),q,1,true)~=nil end return false end for _,instance in ipairs(root:GetDescendants()) do if #results>=maxResults then break end if matches(instance) then table.insert(results,serialize(instance,false)) end end return results end
local function projectAudit(root) local counts={} local total,scripts,remotes,unanchored=0,0,0,0 for _,instance in ipairs(root:GetDescendants()) do total+=1 counts[instance.ClassName]=(counts[instance.ClassName] or 0)+1 if instance:IsA('LuaSourceContainer') then scripts+=1 end if instance:IsA('RemoteEvent') or instance:IsA('RemoteFunction') or instance:IsA('UnreliableRemoteEvent') then remotes+=1 end if instance:IsA('BasePart') and not instance.Anchored then unanchored+=1 end end return{placeId=game.PlaceId,universeId=game.GameId,totalInstances=total,scripts=scripts,remotes=remotes,unanchoredParts=unanchored,classCounts=counts} end
local function performanceAudit(root) local counts={parts=0,unanchored=0,lights=0,emitters=0,trails=0,sounds=0,scripts=0,meshes=0} local hotspots={} for _,instance in ipairs(root:GetDescendants()) do if instance:IsA('BasePart') then counts.parts+=1 if not instance.Anchored then counts.unanchored+=1 end end if instance:IsA('Light') then counts.lights+=1 end if instance:IsA('ParticleEmitter') then counts.emitters+=1 if instance.Rate>100 then table.insert(hotspots,{path=getPath(instance),rate=instance.Rate}) end end if instance:IsA('Trail') then counts.trails+=1 end if instance:IsA('Sound') then counts.sounds+=1 end if instance:IsA('LuaSourceContainer') then counts.scripts+=1 end if instance:IsA('MeshPart') then counts.meshes+=1 end end return{counts=counts,hotspots=hotspots} end
local function securityAudit(root) local findings={} local function add(severity,path,rule,detail)table.insert(findings,{severity=severity,path=path,rule=rule,detail=detail})end for _,instance in ipairs(root:GetDescendants()) do if instance:IsA('LuaSourceContainer') then local ok,source=pcall(function()return instance.Source end) if ok then if source:find('loadstring%s*%(') then add('high',getPath(instance),'dynamic_code','loadstring detected') end if source:find('require%s*%(%s*%d+%s*%)') then add('medium',getPath(instance),'external_require','numeric require detected') end if source:find('OnServerEvent') then add('medium',getPath(instance),'remote_trust_review','Server remote handler requires validation review') end if source:find('HttpService') and(source:find('GetAsync') or source:find('PostAsync')) then add('medium',getPath(instance),'http_dependency','HTTP dependency detected') end end end end return{count=#findings,findings=findings} end
local function assetAudit(root) local assets={} local seen={} local function add(id,kind,path) local number=tostring(id):match('%d+') if not number then return end local key=kind..':'..number if seen[key] then return end seen[key]=true table.insert(assets,{id=number,kind=kind,path=path}) end for _,instance in ipairs(root:GetDescendants()) do for _,property in ipairs({'SoundId','Texture','TextureId','MeshId','AnimationId','Image'}) do local ok,value=pcall(function()return instance[property]end) if ok and type(value)=='string' then for id in value:gmatch('rbxassetid://(%d+)') do add(id,property,getPath(instance)) end end end if instance:IsA('LuaSourceContainer') then local ok,source=pcall(function()return instance.Source end) if ok then for id in source:gmatch('rbxassetid://(%d+)') do add(id,'script',getPath(instance)) end end end end return{count=#assets,assets=assets,note='Static inventory; Roblox ownership/moderation/network validity must still be verified by Studio.'} end
local function runtimeOutput(limit,filter) local result={} for i=math.max(1,#logs-limit+1),#logs do local entry=logs[i] local ok=filter=='all' or(filter=='error' and entry.type:find('Error'))or(filter=='warning' and entry.type:find('Warning'))or(filter=='output' and entry.type:find('Output')) if ok then table.insert(result,entry) end end return result end
local function diagnostics(limit) local output=runtimeOutput(limit,'all') local errors,warnings=0,0 for _,entry in ipairs(output) do if entry.type:find('Error') then errors+=1 elseif entry.type:find('Warning') then warnings+=1 end end return{errors=errors,warnings=warnings,output=output,runtime={studio=RunService:IsStudio(),running=RunService:IsRunning(),edit=RunService:IsEdit(),runMode=RunService:IsRunMode()}} end
local function createSnapshot(name,rootPath,depth) local data={version=1,name=name,root=rootPath,createdAt=os.time(),tree=tree(find(rootPath)or game,depth,true)} plugin:SetSetting('MCP_SNAPSHOT_'..name,HttpService:JSONEncode(data)) return{ok=true,name=name,root=rootPath} end
local function restoreSnapshot(name,dryRun) local raw=plugin:GetSetting('MCP_SNAPSHOT_'..name) if not raw then error('Snapshot not found: '..name) end local data=HttpService:JSONDecode(raw) local root=find(data.root)or game local changes={} local function restore(parent,node) local target=parent:FindFirstChild(node.name) if not target then if dryRun then table.insert(changes,{action='create',path=parent:GetFullName()..'.'..node.name,className=node.className}) return end target=Instance.new(node.className) target.Name=node.name target.Parent=parent table.insert(changes,{action='create',path=getPath(target)}) end for property,value in pairs(node.properties or{}) do setProp(target,property,value) end if node.children then for _,child in ipairs(node.children) do restore(target,child) end end end for _,child in ipairs(data.tree.children or{}) do restore(root,child) end if not dryRun then ChangeHistoryService:SetWaypoint('MCP Restore Snapshot') end return{ok=true,dryRun=dryRun,changes=changes} end
local testActive=false local function playTest(mode,players,args) if testActive then return{ok=false,error='A Studio test is already active'} end testActive=true local ok,result=pcall(function()if mode=='multiplayer' then return StudioTestService:ExecuteMultiplayerTestAsync(players,args) elseif mode=='run' then return StudioTestService:ExecuteRunModeAsync(args) else return StudioTestService:ExecutePlayModeAsync(args) end end) testActive=false if ok then return{ok=true,result=result,output=runtimeOutput(100,'all')} end return{ok=false,error=tostring(result)} end
local function stopTest()local ok,result=pcall(function()if StudioTestService:CanLeaveTest() then StudioTestService:LeaveTest() end end)testActive=false return{ok=ok,error=ok and nil or tostring(result)}end
local function connect()local selection={}for _,instance in ipairs(Selection:Get())do table.insert(selection,{path=getPath(instance),name=instance.Name,className=instance.ClassName})end local ok,data=request('POST','/connect',{pluginVersion=VERSION,studioVersion=tostring(version and version()or'unknown'),placeId=game.PlaceId,universeId=game.GameId,gameName=game.Name,selection=selection})if not ok then connected=false status.Text='MCP: disconnected\n'..tostring(data) return end sessionId=data.sessionId connected=true status.Text='MCP: connected\n127.0.0.1:58888\n'..game.Name end
local function heartbeat()if not connected then return end local selection={}for _,instance in ipairs(Selection:Get())do table.insert(selection,{path=getPath(instance),name=instance.Name,className=instance.ClassName})end request('POST','/heartbeat',{sessionId=sessionId,state={selection=selection,placeId=game.PlaceId,universeId=game.GameId,gameName=game.Name,status='connected'}})end
local function poll()if not connected then return end local ok,response=request('GET','/poll?sessionId='..HttpService:UrlEncode(sessionId))if not ok or not response.command then return end local command=response.command local p=command.params or{} local success,value=pcall(function()local method=command.method if method=='tree' then return tree(find(p.path)or game,p.depth or 2,p.includeProperties==true) elseif method=='search' then return search(find(p.root)or game,p.query or'',p.mode or'name',p.maxResults or 100) elseif method=='getSelection' then local a={}for _,instance in ipairs(Selection:Get())do table.insert(a,serialize(instance,false))end return a elseif method=='setSelection' then local a={}for _,itemPath in ipairs(p.paths or{})do local instance=find(itemPath)if instance then table.insert(a,instance)end end Selection:Set(a)return{count=#a} elseif method=='readScript' then local instance=find(p.path)if not instance or not instance:IsA('LuaSourceContainer')then error('Lua source not found')end return{path=getPath(instance),className=instance.ClassName,source=instance.Source} elseif method=='writeScript' then local instance=find(p.path)if not instance and p.createIfMissing then local a=split(p.path)local name=table.remove(a)local parent=find(table.concat(a,'.'))if not parent then error('Parent not found')end instance=Instance.new(p.className or'ModuleScript')instance.Name=name instance.Parent=parent end if not instance or not instance:IsA('LuaSourceContainer')then error('Script not found')end instance.Source=p.source or''ChangeHistoryService:SetWaypoint('MCP Write Script')return{path=getPath(instance),length=#instance.Source} elseif method=='createInstance' then local parent=find(p.parent or'game.Workspace')or workspace local instance=Instance.new(p.className)if p.name then instance.Name=p.name end for property,value2 in pairs(p.properties or{})do local good,err=setProp(instance,property,value2)if not good then error(property..': '..tostring(err))end end instance.Parent=parent ChangeHistoryService:SetWaypoint('MCP Create Instance')return serialize(instance,true) elseif method=='setProperties' then local instance=find(p.path)if not instance then error('Instance not found')end local failures={}for property,value2 in pairs(p.properties or{})do local good,err=setProp(instance,property,value2)if not good then table.insert(failures,{property=property,error=tostring(err)})end end ChangeHistoryService:SetWaypoint('MCP Set Properties')return{path=getPath(instance),failures=failures} elseif method=='deleteInstance' then local instance=find(p.path)if not instance or instance==game then error('Cannot delete target')end local old=getPath(instance)instance:Destroy()ChangeHistoryService:SetWaypoint('MCP Delete Instance')return{deleted=old} elseif method=='executeLuau' then local fn,compileError=loadstring(p.code or'')if not fn then error(compileError)end local good,resultValue=pcall(fn)if not good then error(resultValue)end return encodeValue(resultValue) elseif method=='status' or method=='diagnostics' then return diagnostics(p.limit or 100) elseif method=='runtimeOutput' then return runtimeOutput(p.limit or 100,p.type or'all') elseif method=='projectAudit' then return projectAudit(find(p.root)or game) elseif method=='performanceAudit' then return performanceAudit(find(p.root)or game) elseif method=='securityAudit' then return securityAudit(find(p.root)or game) elseif method=='assetAudit' then return assetAudit(find(p.root)or game) elseif method=='snapshotCreate' then return createSnapshot(p.name,p.root or'game',p.depth or 5) elseif method=='snapshotRestore' then return restoreSnapshot(p.name,p.dryRun==true) elseif method=='playTest' then return playTest(p.mode or'play',p.players or 1,p.args) elseif method=='stopTest' then return stopTest() end error('Unknown method: '..tostring(method))end) request('POST','/result',{sessionId=sessionId,id=command.id,ok=success,result=success and value or nil,error=success and nil or tostring(value)})end
task.spawn(function()while running do if not connected then connect()else heartbeat()end task.wait(2.5)end end)task.spawn(function()while running do if connected then poll()end task.wait(0.35)end end)plugin.Unloading:Connect(function()running=false end)
